      longH: 'लंबा निबंध (कक्षा 5 से 10)',
      long: [
        { h: 'प्रस्तावना', p: ['घर के बाद अगर कोई जगह हमें सबसे ज़्यादा सिखाती है, तो वह है हमारा विद्यालय। विद्यालय को ज्ञान का मंदिर कहा जाता है, क्योंकि यहाँ हम केवल किताबें ही नहीं पढ़ते, बल्कि अच्छा इंसान बनना भी सीखते हैं। मेरे विद्यालय का नाम ______ है और मुझे इसका विद्यार्थी होने पर गर्व है।'] },
        { h: 'विद्यालय का भवन', p: ['मेरा विद्यालय एक खुली और शांत जगह पर बना है। इसकी इमारत दो/तीन मंज़िला है और चारों ओर हरे पेड़ और फूलों की क्यारियाँ हैं। कक्षाएँ बड़ी, रोशनी वाली और हवादार हैं। हर कक्षा में बोर्ड, पंखे और बैठने के लिए अच्छे डेस्क हैं। विद्यालय में पीने के साफ़ पानी और अलग-अलग शौचालयों की भी व्यवस्था है।'] },
        { h: 'पुस्तकालय, प्रयोगशाला और कंप्यूटर कक्ष', p: ['हमारे विद्यालय का पुस्तकालय मेरी सबसे पसंदीदा जगह है। यहाँ कहानियों, विज्ञान, इतिहास और सामान्य ज्ञान की सैकड़ों किताबें और अख़बार हैं। विज्ञान की प्रयोगशाला में हम ख़ुद प्रयोग करके सीखते हैं। कंप्यूटर कक्ष में हमें टाइपिंग, इंटरनेट का सही उपयोग और छोटे-छोटे प्रोग्राम बनाना सिखाया जाता है।'] },
        { h: 'हमारे शिक्षक', p: ['किसी भी विद्यालय की असली ताक़त उसके शिक्षक होते हैं। हमारे प्रधानाचार्य जी बहुत अनुशासनप्रिय और दयालु हैं। हमारे शिक्षक हर विषय को आसान उदाहरणों से समझाते हैं और कमज़ोर बच्चों पर ख़ास ध्यान देते हैं। वे हमें सच बोलना, बड़ों का आदर करना और मेहनत करना भी सिखाते हैं।'] },
        { h: 'खेल-कूद और दूसरी गतिविधियाँ', p: ['हमारे विद्यालय में पढ़ाई के साथ खेल-कूद को भी बराबर महत्व दिया जाता है। बड़े मैदान में हम क्रिकेट, फ़ुटबॉल, खो-खो और कबड्डी खेलते हैं। हर साल खेल दिवस होता है। इसके अलावा भाषण, कविता-पाठ, चित्रकला, निबंध लेखन और विज्ञान प्रदर्शनी जैसी प्रतियोगिताएँ भी होती हैं। 15 अगस्त, 26 जनवरी, शिक्षक दिवस और बाल दिवस पर रंगारंग कार्यक्रम होते हैं।'] },
        { h: 'अनुशासन', p: ['मेरे विद्यालय में अनुशासन का बहुत ध्यान रखा जाता है। सभी विद्यार्थी साफ़ वर्दी पहनकर समय पर आते हैं। प्रार्थना सभा में हम पंक्ति में खड़े होते हैं और राष्ट्रगान गाते हैं। कक्षा में शोर नहीं करते और विद्यालय को साफ़ रखते हैं। यही आदतें आगे जीवन में भी काम आती हैं।'] },
        { h: 'उपसंहार', p: ['मेरा विद्यालय मेरे लिए दूसरे घर जैसा है। यहाँ मुझे अच्छे शिक्षक, सच्चे दोस्त और ढेर सारा ज्ञान मिला है। मैं चाहता/चाहती हूँ कि मैं ख़ूब पढ़-लिखकर एक अच्छा नागरिक बनूँ और अपने विद्यालय का नाम रोशन करूँ।'] },
      ],
      faq: [
        ['मेरा विद्यालय निबंध में कौन-कौन से शीर्षक लिखें?', 'प्रस्तावना, विद्यालय का भवन, पुस्तकालय और प्रयोगशाला, शिक्षक, खेल-कूद और गतिविधियाँ, अनुशासन और उपसंहार।'],
        ['विद्यालय को ज्ञान का मंदिर क्यों कहते हैं?', 'क्योंकि यहाँ हमें पढ़ाई के साथ अच्छे संस्कार, अनुशासन और मिल-जुलकर रहना सिखाया जाता है, जैसे मंदिर में मन पवित्र होता है वैसे ही विद्यालय में मन ज्ञान से भरता है।'],
        ['क्या मैं यह निबंध अपने स्कूल के हिसाब से बदल सकता हूँ?', 'हाँ, ज़रूर। ______ की जगह अपने स्कूल का नाम लिखें और भवन, खेल या गतिविधियों में अपने स्कूल की असली बातें जोड़ें — इससे निबंध और अच्छा बनेगा।'],
      ],
